<!doctype html>
<html lang="zh-CN">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>订阅泄露风险分析</title>
    <style>
        :root{--bg:#eef2f1;--ink:#17211f;--muted:#6d7977;--line:#d8dfdd;--paper:#fff;--soft:#f7f9f8;--teal:#087f72;--teal-soft:#e4f4f1;--navy:#1d302e;--red:#bf3c2f;--red-soft:#fff0ed;--amber:#b06a0a;--amber-soft:#fff6e6}
        *{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 Arial,"Microsoft YaHei",sans-serif}.shell{max-width:1580px;margin:auto;padding:22px 28px 40px}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:18px}.eyebrow{color:var(--teal);font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.top h1{margin:5px 0 4px;font-size:25px}.top p{margin:0;color:var(--muted)}button,input,select{font:inherit}.actions{display:flex;gap:8px}.button{border:1px solid var(--line);border-radius:4px;background:var(--paper);color:var(--ink);padding:8px 11px;cursor:pointer}.button.primary{border-color:var(--navy);background:var(--navy);color:#fff}.filters{display:flex;align-items:end;gap:10px;flex-wrap:wrap;margin-top:20px;padding:14px 15px;border:1px solid var(--line);background:var(--paper)}.filters label{display:grid;gap:4px;color:var(--muted);font-size:12px}.filters input,.filters select{width:145px;min-height:34px;padding:7px 8px;border:1px solid var(--line);border-radius:3px;background:#fff;color:var(--ink)}.filters .wide input{width:200px}.summary{display:grid;grid-template-columns:repeat(5,1fr);gap:1px;margin-top:13px;border:1px solid var(--line);background:var(--line)}.metric{min-height:88px;padding:13px 15px;background:var(--paper)}.metric span{display:block;color:var(--muted);font-size:12px}.metric b{display:block;margin-top:6px;font-size:24px;line-height:1}.metric small{display:block;margin-top:5px;color:var(--red);font-size:11px}.workspace{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(390px,.75fr);gap:14px;margin-top:14px}.panel{min-width:0;border:1px solid var(--line);background:var(--paper)}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:14px 16px;border-bottom:1px solid var(--line)}.panel-head h2{margin:0;font-size:16px}.panel-head p{margin:3px 0 0;color:var(--muted);font-size:12px}.tabs{display:flex;gap:2px;padding:9px 11px 0;border-bottom:1px solid var(--line);overflow:auto}.tab{padding:8px 10px;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--muted);white-space:nowrap;cursor:pointer}.tab.active{border-bottom-color:var(--teal);color:var(--teal);font-weight:700}.table-wrap{overflow:auto}.ranking-table,.logs{width:100%;border-collapse:collapse}.ranking-table{min-width:760px}.ranking-table th,.ranking-table td,.logs th,.logs td{padding:10px 11px;border-bottom:1px solid #edf0ef;text-align:left;vertical-align:middle}.ranking-table th,.logs th{background:var(--soft);color:var(--muted);font-size:11px;font-weight:700}.ranking-table tbody tr{cursor:pointer}.ranking-table tbody tr:hover,.ranking-table tbody tr.selected{background:#eff8f6}.account{display:flex;align-items:center;gap:8px;min-width:175px}.avatar{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--teal-soft);color:var(--teal);font-size:11px;font-weight:700}.account b,.account small{display:block}.account small,.subtle{color:var(--muted);font-size:11px}.risk{font-weight:700}.risk.high{color:var(--red)}.risk.medium{color:var(--amber)}.risk.low{color:var(--teal)}.risk-bar{width:70px;height:5px;margin-top:4px;background:#e4eae8}.risk-bar i{display:block;height:100%;background:var(--red)}.chip{display:inline-block;padding:2px 5px;margin:2px 2px 0 0;border:1px solid var(--line);border-radius:3px;color:#50605d;font-size:11px;white-space:nowrap}.chip.red{border-color:#efc7c1;background:var(--red-soft);color:var(--red)}.chip.amber{border-color:#efd7ae;background:var(--amber-soft);color:var(--amber)}.detail{background:var(--navy);border-color:var(--navy);color:#edf6f3}.detail .panel-head{border-color:#38504c}.detail .panel-head p,.detail .muted{color:#a8bfba}.detail-body{padding:16px}.case-title{display:flex;justify-content:space-between;align-items:start;gap:12px}.case-title h3{margin:0;font-size:18px}.case-title p{margin:4px 0 0;color:#a8bfba;font-size:12px}.score{min-width:64px;padding:7px 9px;text-align:center;border:1px solid #75443f;background:#4e2c2b;color:#ffb6aa}.score b{display:block;font-size:22px}.score small{font-size:10px}.detail-section{margin-top:20px}.section-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;color:#d8e8e4;font-size:12px;font-weight:700}.section-title span{color:#91aaa5;font-weight:400}.ip-list{display:grid;gap:7px}.ip-row{display:grid;grid-template-columns:8px minmax(0,1fr) auto;gap:8px;align-items:center;padding:8px 9px;background:#29413d;border:1px solid #38524d}.ip-dot{width:7px;height:7px;border-radius:50%;background:#ef8f83}.ip-row b,.ip-row small{display:block}.ip-row small{color:#9eb6b1;font-size:11px}.ip-count{color:#dceae7;font-size:12px}.timeline{border-left:1px solid #55706a;padding-left:14px;margin-left:4px}.event{position:relative;margin-bottom:13px}.event:before{content:"";position:absolute;left:-18px;top:5px;width:7px;height:7px;border:2px solid var(--navy);border-radius:50%;background:#8ed0c5}.event time{display:block;color:#8facaa;font-size:11px}.event b{display:block;margin-top:2px;font-size:12px}.event p{margin:2px 0 0;color:#a8bfba;font-size:11px}.notice{margin-top:16px;padding:9px 10px;border-left:3px solid #e69a57;background:#2e403d;color:#d8e8e4;font-size:11px}.aux-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:14px}.mini-list{padding:5px 15px 10px}.mini-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:9px 0;border-bottom:1px solid #edf0ef}.mini-row:last-child{border-bottom:0}.mini-row b,.mini-row small{display:block}.mini-row small{color:var(--muted);font-size:11px}.mini-row strong{color:var(--red);font-size:12px}.raw{margin-top:14px}.raw .table-wrap{max-height:470px}.logs{min-width:980px;font-size:12px}.logs td{vertical-align:top}.ua{max-width:330px;overflow-wrap:anywhere;font-family:Consolas,monospace;font-size:11px}.badge{display:inline-block;padding:2px 6px;border-radius:9px;background:var(--teal-soft);color:#06685f;font-size:11px}.badge.red{background:var(--red-soft);color:var(--red)}.pager{display:flex;align-items:center;gap:8px;padding:11px 14px}.pager span{color:var(--muted);font-size:12px}.pager button:disabled{opacity:.45;cursor:not-allowed}.state{padding:28px 15px;color:var(--muted)}.empty{padding:18px;color:var(--muted)}@media(max-width:1050px){.workspace{grid-template-columns:1fr}.summary{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.shell{padding:15px 12px 28px}.top{display:block}.actions{margin-top:12px}.filters>*{width:calc(50% - 6px)}.filters input,.filters select,.filters .wide input{width:100%}.summary{grid-template-columns:repeat(2,1fr)}.aux-grid{grid-template-columns:1fr}.metric{min-height:77px;padding:10px}.metric b{font-size:21px}}
    </style>
</head>
<body>
<main class="shell">
    <header class="top">
        <div><div class="eyebrow">SECURITY / SUBSCRIPTION EXPOSURE</div><h1>订阅泄露风险分析</h1><p>优先定位一个账号被多个陌生来源使用的证据链</p></div>
        <div class="actions"><button id="logout" class="button" type="button">退出</button><button id="refresh" class="button primary" type="button">刷新数据</button></div>
    </header>
    <form id="filters" class="filters">
        <label>开始日期<input name="start" type="date"></label>
        <label>结束日期<input name="end" type="date"></label>
        <label class="wide">账号 / IP<input name="email" placeholder="邮箱关键字"></label>
        <label>精确 IP<input name="ip" placeholder="例如 1.1.1.1"></label>
        <label>国家<input name="country" maxlength="2" placeholder="US"></label>
        <label class="wide">User-Agent<input name="user_agent" placeholder="客户端关键字"></label>
        <label>最低欺诈分<select name="min_fraud_score"><option value="">全部</option><option value="60">60 以上</option><option value="70">70 以上</option><option value="85">85 以上</option></select></label>
        <label>来源<select name="proxy_only"><option value="">全部来源</option><option value="1">仅代理 / 机房</option></select></label>
        <label>伪装<select name="masked_only"><option value="">全部请求</option><option value="1">仅已伪装</option></select></label>
        <button class="button primary" type="submit">应用筛选</button><button id="reset" class="button" type="button">重置</button>
    </form>
    <section id="summary" class="summary"></section>
    <section class="workspace">
        <section class="panel">
            <div class="panel-head"><div><h2>订阅泄露风险榜</h2><p>按陌生来源、扩散速度和网络风险综合排序</p></div><select id="ranking-sort" class="button"><option value="risk_users">综合风险</option><option value="short_term_spread">短时扩散</option><option value="proxy_users">代理来源</option><option value="cross_region_users">跨地区切换</option></select></div>
            <nav id="tabs" class="tabs"></nav>
            <div id="ranking-state" class="state">正在加载榜单...</div>
            <div class="table-wrap"><table id="ranking-table" class="ranking-table" hidden><thead></thead><tbody></tbody></table></div><div class="pager ranking-pager"><button id="ranking-prev" class="button" type="button">上一页</button><span id="ranking-page"></span><button id="ranking-next" class="button" type="button">下一页</button></div>
        </section>
        <aside class="panel detail">
            <div class="panel-head"><div><h2>证据详情</h2><p>点击榜单中的账号查看完整使用轨迹</p></div></div>
            <div id="evidence" class="detail-body"><p class="muted">选择一个高风险账号后，这里会显示关联 IP、来源网络和访问时间线。</p></div>
        </aside>
    </section>
    <section id="aux-grid" class="aux-grid"></section>
    <section class="panel raw"><div class="panel-head"><div><h2>原始访问记录</h2><p>所有记录均继承当前筛选条件</p></div></div><div id="raw-state" class="state">正在加载记录...</div><div class="table-wrap"><table id="logs" class="logs" hidden><thead><tr><th>时间</th><th>账号</th><th>IP / 地理位置</th><th>网络风险</th><th>User-Agent</th><th>规则结果</th></tr></thead><tbody></tbody></table></div><div class="pager"><button id="prev" class="button" type="button">上一页</button><span id="page"></span><button id="next" class="button" type="button">下一页</button></div></section>
</main>
<script>
const form=document.querySelector('#filters'),summary=document.querySelector('#summary'),tabs=document.querySelector('#tabs'),rankingTable=document.querySelector('#ranking-table'),rankingState=document.querySelector('#ranking-state'),auxGrid=document.querySelector('#aux-grid'),evidence=document.querySelector('#evidence'),rawState=document.querySelector('#raw-state'),logs=document.querySelector('#logs'),logBody=logs.querySelector('tbody'),pageText=document.querySelector('#page'),prev=document.querySelector('#prev'),next=document.querySelector('#next'),dataUrl='{{ $analysisBaseUrl }}/data',logoutUrl='{{ $analysisBaseUrl }}/logout';
let payload=null,currentTab='risk_users',page=1,total=0,pageSize=10,rankingPage=1,rankingPageSize=10,selectedUserId=null;
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const formatDate=value=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'-';
const initials=email=>String(email||'?').slice(0,2).toUpperCase();
const tabMeta={risk_users:['风险总榜','账号综合泄露风险'],short_term_spread:['短时扩散榜','1 小时内新增多个来源 IP'],shared_ips:['高关联 IP 榜','一个 IP 同时使用多个账号'],proxy_users:['代理来源榜','代理、VPN、机房来源账号'],shared_user_agents:['共享 User-Agent 榜','同一客户端特征关联多个账号'],cross_region_users:['跨地区切换榜','短时间从多个地区访问同一账号'],high_frequency_users:['异常高频访问榜','短时间请求突增的账号'],rule_hits:['命中规则榜','查看伪装规则的触发分布']};
function renderSummary(data){const items=[['suspected_leaks','疑似泄露账号','重点核查对象'],['distinct_ips','来源 IP 数','当前筛选范围'],['shared_ip_count','多账号关联 IP','重点证据线索'],['short_term_spread_count','短时扩散事件','1 小时窗口'],['high_risk_requests','高风险请求','欺诈分 ≥ 70']];summary.innerHTML=items.map(([key,label,note])=>'<div class="metric"><span>'+label+'</span><b>'+escapeHtml(data[key]??0)+'</b><small>'+note+'</small></div>').join('')}
function renderTabs(){tabs.innerHTML=Object.entries(tabMeta).map(([key,[label]])=>'<button type="button" class="tab '+(key===currentTab?'active':'')+'" data-tab="'+key+'">'+label+'</button>').join('')}
function rankingRows(key){return payload.rankings[key]||[]}
function renderRanking(){const rows=rankingRows(currentTab);const totalRankingPages=Math.max(1,Math.ceil(rows.length/rankingPageSize));rankingPage=Math.min(rankingPage,totalRankingPages);const visibleRows=rows.slice((rankingPage-1)*rankingPageSize,rankingPage*rankingPageSize);rankingState.hidden=visibleRows.length>0;rankingState.textContent=visibleRows.length?'':'当前筛选范围暂无数据';rankingTable.hidden=!visibleRows.length;let headers,html;if(['risk_users','proxy_users','cross_region_users','high_frequency_users'].includes(currentTab)){headers=currentTab==='risk_users'?['#','账号','风险','陌生 IP','关联证据','最近异常']:['#','账号','核心指标','请求数','IP / 地区','最近异常'];html=visibleRows.map((row,index)=>{const score=row.risk_score??0;return '<tr class="'+(selectedUserId===row.user_id?'selected':'')+'" data-user-id="'+row.user_id+'"><td>'+((rankingPage-1)*rankingPageSize+index+1).toString().padStart(2,'0')+'</td><td><div class="account"><span class="avatar">'+escapeHtml(initials(row.email))+'</span><span><b>'+escapeHtml(row.email)+'</b><small>用户 ID #'+row.user_id+'</small></span></div></td><td>'+(currentTab==='risk_users'?'<span class="risk '+(score>=70?'high':score>=40?'medium':'low')+'">'+score+'</span><div class="risk-bar"><i style="width:'+score+'%"></i></div>':'<b>'+escapeHtml(row.proxy_ips??row.distinct_countries??row.request_count??0)+'</b>')+'</td><td><b>'+escapeHtml(row.distinct_ips??row.proxy_requests??row.request_count??0)+'</b></td><td>'+(currentTab==='risk_users'?'<span class="chip red">'+escapeHtml((row.signals||[]).map(s=>s.label+' '+s.count).join(' · ')||'需要关注')+'</span>':escapeHtml(row.distinct_countries??row.proxy_requests??'-'))+'</td><td class="subtle">'+formatDate(row.last_seen_at)+'</td></tr>'}).join('')}else if(['shared_ips','shared_user_agents'].includes(currentTab)){headers=currentTab==='shared_ips'?['#','IP','请求数','关联账号','地区数','风险']:['#','User-Agent','请求数','关联账号','关联 IP','最近'];html=visibleRows.map((row,index)=>'<tr><td>'+((rankingPage-1)*rankingPageSize+index+1).toString().padStart(2,'0')+'</td><td><b>'+escapeHtml(row.ip||row.user_agent)+'</b></td><td>'+row.request_count+'</td><td>'+row.distinct_users+'</td><td>'+escapeHtml(row.country_count??row.distinct_ips??'-')+'</td><td>'+escapeHtml(row.max_fraud_score??formatDate(row.latest_seen_at))+'</td></tr>').join('')}else if(currentTab==='short_term_spread'){headers=['#','账号','新增 IP','窗口请求','窗口开始','窗口结束'];html=visibleRows.map((row,index)=>'<tr data-user-id="'+row.user_id+'"><td>'+((rankingPage-1)*rankingPageSize+index+1).toString().padStart(2,'0')+'</td><td><b>'+escapeHtml(row.email)+'</b><small class="subtle"> #'+row.user_id+'</small></td><td><span class="risk high">'+row.spread_ip_count+'</span></td><td>'+row.request_count+'</td><td class="subtle">'+formatDate(row.window_start)+'</td><td class="subtle">'+formatDate(row.window_end)+'</td></tr>').join('')}else{headers=['#','规则','请求数','关联账号','最近触发'];html=visibleRows.map((row,index)=>'<tr><td>'+((rankingPage-1)*rankingPageSize+index+1).toString().padStart(2,'0')+'</td><td><b>'+escapeHtml(row.reason)+'</b></td><td>'+row.request_count+'</td><td>'+row.distinct_users+'</td><td class="subtle">'+formatDate(row.latest_seen_at)+'</td></tr>').join('')}rankingTable.querySelector('thead').innerHTML='<tr>'+headers.map(header=>'<th>'+header+'</th>').join('')+'</tr>';rankingTable.querySelector('tbody').innerHTML=html;document.querySelector('#ranking-page').textContent='第 '+rankingPage+' 页 / 共 '+totalRankingPages+' 页';document.querySelector('#ranking-prev').disabled=rankingPage<=1;document.querySelector('#ranking-next').disabled=rankingPage>=totalRankingPages}
function renderEvidence(){const item=(payload.account_evidence||[]).find(row=>row.user_id===selectedUserId);if(!item){evidence.innerHTML='<p class="muted">选择一个高风险账号后，这里会显示关联 IP、来源网络和访问时间线。</p>';return}evidence.innerHTML='<div class="case-title"><div><h3>'+escapeHtml(item.email)+'</h3><p>用户 ID #'+item.user_id+' · 仅代表疑似泄露特征，不等于已确认违规</p></div><div class="score"><b>'+item.risk_score+'</b><small>'+escapeHtml(item.risk_level)+'</small></div></div><div class="detail-section"><div class="section-title">关联来源 IP <span>'+item.ips.length+' 个</span></div><div class="ip-list">'+item.ips.map(ip=>'<div class="ip-row"><i class="ip-dot"></i><span><b>'+escapeHtml(ip.ip)+'</b><small>'+escapeHtml([ip.country,ip.region,ip.city,ip.isp,ip.as_name].filter(Boolean).join(' · ')||ip.country_code||'未知来源')+' · '+(ip.is_proxy?'代理/机房':'普通网络')+' · 关联 '+ip.related_users+' 个账号</small></span><span class="ip-count">'+ip.request_count+' 次</span></div>').join('')+'</div></div><div class="detail-section"><div class="section-title">异常访问时间线 <span>最近 '+item.timeline.length+' 条</span></div><div class="timeline">'+item.timeline.slice(0,12).map(row=>'<div class="event"><time>'+formatDate(row.created_at)+' · '+escapeHtml(row.ip||'无 IP')+'</time><b>'+(row.is_proxy?'代理/机房来源':'访问记录')+' · 欺诈分 '+(row.fraud_score??'-')+'</b><p>'+escapeHtml([row.country,row.city,row.user_agent,row.reason].filter(Boolean).join(' · ')||'无额外标记')+'</p></div>').join('')+'</div></div><div class="notice">调查建议：先核对账号本人常用 IP，再结合共享 IP、短时扩散和 User-Agent 证据决定是否要求重新登录或冻结。</div>'}
function renderAux(){const configs=[['proxy_users','代理来源榜','proxy_ips','个代理 IP'],['shared_user_agents','共享 User-Agent 榜','distinct_users','个账号'],['cross_region_users','跨地区切换榜','distinct_countries','个地区'],['high_frequency_users','异常高频访问榜','request_count','次请求'],['rule_hits','命中规则榜','request_count','次命中']];auxGrid.innerHTML=configs.map(([key,title,field,suffix])=>{const rows=rankingRows(key).slice(0,5);return '<section class="panel"><div class="panel-head"><div><h2>'+title+'</h2><p>'+tabMeta[key][1]+'</p></div></div><div class="mini-list">'+(rows.length?rows.map(row=>'<div class="mini-row"><span><b>'+escapeHtml(row.email||row.user_agent||row.reason||row.ip)+'</b><small>'+escapeHtml(row.ip||row.distinct_ips||row.distinct_users||'')+'</small></span><strong>'+escapeHtml(row[field]??0)+' '+suffix+'</strong></div>').join(''):'<div class="empty">暂无数据</div>')+'</div></section>'}).join('')}
function renderLogs(data){logBody.innerHTML=(data.data||[]).map(row=>'<tr><td>'+formatDate(row.created_at)+'</td><td>'+escapeHtml(row.email)+'<br><span class="subtle">#'+row.user_id+'</span></td><td>'+escapeHtml(row.ip||'-')+'<br><span class="subtle">'+escapeHtml([row.country_code,row.country,row.city].filter(Boolean).join(' · '))+'</span></td><td>'+(row.is_proxy?'<span class="badge red">代理</span> ':'')+(row.fraud_score>=70?'<span class="badge red">'+row.fraud_score+'</span>':escapeHtml(row.fraud_score??'-'))+'</td><td class="ua">'+escapeHtml(row.user_agent||'-')+'</td><td>'+(row.masked?'<span class="badge">已伪装</span>':'原始域名')+(row.reason?'<br><span class="subtle">'+escapeHtml(row.reason)+'</span>':'')+'</td></tr>').join('');total=data.total;page=data.page;pageText.textContent='第 '+page+' 页 / 共 '+Math.max(1,Math.ceil(total/pageSize))+' 页';prev.disabled=page<=1;next.disabled=page*pageSize>=total;rawState.hidden=!!data.data.length;logs.hidden=!data.data.length}
async function load(){const query=new URLSearchParams(new FormData(form));query.set('page',page);query.set('page_size',pageSize);rankingState.hidden=false;rankingState.textContent='正在加载榜单...';rawState.hidden=false;rawState.textContent='正在加载记录...';try{const response=await fetch(dataUrl+'?'+query,{credentials:'include'});if(response.status===401){location.href='{{ $analysisBaseUrl }}';return}const result=await response.json();if(!response.ok)throw new Error(result.message||'加载失败');payload=result;renderSummary(result.summary);renderTabs();renderRanking();renderAux();renderEvidence();renderLogs(result.logs)}catch(error){rankingState.hidden=false;rankingState.textContent=error.message||'榜单加载失败';rawState.hidden=false;rawState.textContent=error.message||'记录加载失败';logs.hidden=true}}
form.addEventListener('submit',event=>{event.preventDefault();page=1;rankingPage=1;selectedUserId=null;load()});document.querySelector('#reset').addEventListener('click',()=>{form.reset();page=1;rankingPage=1;selectedUserId=null;load()});document.querySelector('#refresh').addEventListener('click',()=>load());document.querySelector('#ranking-sort').addEventListener('change',event=>{currentTab=event.target.value;rankingPage=1;selectedUserId=null;renderTabs();renderRanking();renderEvidence()});tabs.addEventListener('click',event=>{const button=event.target.closest('[data-tab]');if(!button)return;currentTab=button.dataset.tab;rankingPage=1;selectedUserId=null;document.querySelector('#ranking-sort').value=['risk_users','short_term_spread','proxy_users','cross_region_users'].includes(currentTab)?currentTab:'risk_users';renderTabs();renderRanking();renderEvidence()});rankingTable.addEventListener('click',event=>{const row=event.target.closest('[data-user-id]');if(!row)return;selectedUserId=Number(row.dataset.userId);renderRanking();renderEvidence()});document.querySelector('#ranking-prev').addEventListener('click',()=>{if(rankingPage>1){rankingPage--;renderRanking()}});document.querySelector('#ranking-next').addEventListener('click',()=>{const totalRankingPages=Math.max(1,Math.ceil(rankingRows(currentTab).length/rankingPageSize));if(rankingPage<totalRankingPages){rankingPage++;renderRanking()}});prev.addEventListener('click',()=>{if(page>1){page--;load()}});next.addEventListener('click',()=>{if(page*pageSize<total){page++;load()}});document.querySelector('#logout').addEventListener('click',async()=>{await fetch(logoutUrl,{method:'POST',credentials:'include'});location.reload()});load();
</script>
</body>
</html>
